// Reproducible density crossover benchmark: BDR V5 Compact vs V4 Robin Hood.
// Build: g++ -O3 -std=c++17 benchmarks/bdr_v5_density_crossover.cpp -o bdr_cross
#include <algorithm>
#include <chrono>
#include <cmath>
#include <cstdint>
#include <cstdio>
#include <iostream>
#include <random>
#include <string>
#include <vector>
using Clock=std::chrono::steady_clock;
static inline uint64_t mix64(uint64_t x){x+=0x9e3779b97f4a7c15ULL;x=(x^(x>>30))*0xbf58476d1ce4e5b9ULL;x=(x^(x>>27))*0x94d049bb133111ebULL;return x^(x>>31);}static inline uint64_t fnv(const std::string&s,uint64_t h){for(unsigned char c:s){h^=c;h*=1099511628211ULL;}return h;}
struct A{uint32_t rho,phi;uint64_t sig;};struct Enc{uint32_t m,p;A operator()(const std::string&k)const{uint64_t a=mix64(fnv(k,1469598103934665603ULL)),b=mix64(fnv(k,1099511628211ULL));return{uint32_t(a%m),uint32_t(b%p),mix64(a^(b<<1))};}};
struct E{uint64_t key,val;};class Compact{Enc e;std::vector<std::vector<E>> ps;static uint64_t lk(const A&a){return mix64((uint64_t(a.phi)<<48)^a.sig);}public:Compact(uint32_t m,uint32_t p):e{m,p},ps(m){}void build(const std::vector<std::string>&ks){std::vector<uint32_t>c(ps.size());for(auto&k:ks)c[e(k).rho]++;for(size_t i=0;i<ps.size();++i)ps[i].reserve(c[i]);for(size_t i=0;i<ks.size();++i){A a=e(ks[i]);ps[a.rho].push_back({lk(a),i});}for(auto&v:ps)std::sort(v.begin(),v.end(),[](auto&a,auto&b){return a.key<b.key;});}bool get(const std::string&k,uint64_t&v)const{A a=e(k);auto&b=ps[a.rho];uint64_t x=lk(a);auto it=std::lower_bound(b.begin(),b.end(),x,[](const E&e,uint64_t q){return e.key<q;});if(it==b.end()||it->key!=x)return false;v=it->val;return true;}size_t bytes()const{size_t z=ps.capacity()*sizeof(std::vector<E>);for(auto&v:ps)z+=v.capacity()*sizeof(E);return z;}};
struct S{uint64_t key=0,val=0;uint32_t d=0;bool u=false;};class RH{std::vector<S>s;size_t mask;public:RH(size_t c=8):s(c),mask(c-1){}void ins(uint64_t k,uint64_t v){size_t i=mix64(k)&mask;S cur{k,v,0,true};for(;;){S&x=s[i];if(!x.u){x=cur;return;}if(x.key==cur.key){x.val=v;return;}if(x.d<cur.d)std::swap(x,cur);i=(i+1)&mask;++cur.d;}}bool get(uint64_t k,uint64_t&v)const{size_t i=mix64(k)&mask;uint32_t d=0;for(;;){const S&x=s[i];if(!x.u||x.d<d)return false;if(x.key==k){v=x.val;return true;}i=(i+1)&mask;++d;}}size_t bytes()const{return s.capacity()*sizeof(S);}};
class Robin{Enc e;std::vector<RH>ps;size_t cap;static uint64_t lk(const A&a){return mix64((uint64_t(a.phi)<<48)^a.sig);}public:Robin(uint32_t m,uint32_t p,size_t n):e{m,p}{double avg=(double)n/m;cap=8;while(cap<(size_t)ceil((avg*1.5+8)/0.70))cap<<=1;ps.reserve(m);for(uint32_t i=0;i<m;++i)ps.emplace_back(cap);}void build(const std::vector<std::string>&ks){for(size_t i=0;i<ks.size();++i){A a=e(ks[i]);ps[a.rho].ins(lk(a),i);}}bool get(const std::string&k,uint64_t&v)const{A a=e(k);return ps[a.rho].get(lk(a),v);}size_t bytes()const{size_t z=ps.capacity()*sizeof(RH);for(auto&v:ps)z+=v.bytes();return z;}};
struct R{double mops,p50,p99;};template<class D>R bench(D&d,const std::vector<std::string>&ks,size_t q){std::mt19937_64 r(42);std::uniform_int_distribution<size_t>pick(0,ks.size()-1);std::vector<double>lat;lat.reserve(5000);volatile uint64_t sink=0;auto t0=Clock::now();for(size_t i=0;i<q;++i){auto s=Clock::now();uint64_t v=0;d.get(ks[pick(r)],v);if(i<5000)lat.push_back(std::chrono::duration<double,std::nano>(Clock::now()-s).count()/1000.0);sink^=v;}double sec=std::chrono::duration<double>(Clock::now()-t0).count();std::sort(lat.begin(),lat.end());return{q/sec/1e6,lat[lat.size()/2],lat[(size_t)(lat.size()*0.99)-1]};}
int main(){constexpr size_t N=500000,Q=250000;constexpr uint32_t P=65536;std::vector<std::string>ks;ks.reserve(N);for(size_t i=0;i<N;++i){char b[48];snprintf(b,sizeof(b),"ETBRA_RESOLUTIVE_KEY_%08zu",i);ks.emplace_back(b);}std::cout<<"M,lambda,engine,build_s,mops,p50_us,p99_us,bytes_per_record\n";for(uint32_t M:{500000,100000,50000,10000,5000,1000,500,250}){Compact c(M,P);auto a=Clock::now();c.build(ks);auto b=Clock::now();auto rc=bench(c,ks,Q);std::cout<<M<<','<<(double)N/M<<",Compact,"<<std::chrono::duration<double>(b-a).count()<<','<<rc.mops<<','<<rc.p50<<','<<rc.p99<<','<<(double)c.bytes()/N<<'\n';Robin h(M,P,N);a=Clock::now();h.build(ks);b=Clock::now();auto rh=bench(h,ks,Q);std::cout<<M<<','<<(double)N/M<<",Robin,"<<std::chrono::duration<double>(b-a).count()<<','<<rh.mops<<','<<rh.p50<<','<<rh.p99<<','<<(double)h.bytes()/N<<'\n';}}
